package net.officefloor.hq.app.asof;

import javax.sql.DataSource;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/** Routes the app's data source (see {@link AsOfDataSource}), so a request answered as of a date reads the sheet as it then stood. */
@Configuration
public class AsOfConfig {

    @Bean
    public static BeanPostProcessor asOfDataSourceRouting() {
        return new BeanPostProcessor() {
            @Override
            public Object postProcessAfterInitialization(Object bean, String beanName) {
                return bean instanceof DataSource ds && !(bean instanceof AsOfDataSource) ? new AsOfDataSource(ds)
                        : bean;
            }
        };
    }
}
package net.officefloor.hq.app.asof;

import javax.sql.DataSource;

/**
 * The store the request in hand reads: while a screen shows a sheet as of a date, the sheet as it then stood (see
 * {@link AsOfService#storeAsOf}); otherwise none, and the request reads the store itself.
 */
public final class AsOfContext {

    private static final ThreadLocal<DataSource> STORE = new ThreadLocal<>();

    private AsOfContext() {
    }

    static void enter(DataSource store) {
        STORE.set(store);
    }

    static void leave() {
        STORE.remove();
    }

    /** The store the request reads as of a date; null when it reads the store itself. */
    static DataSource store() {
        return STORE.get();
    }

    /** Whether the request in hand is answered as of a date: it changes nothing and writes no audit record. */
    public static boolean active() {
        return STORE.get() != null;
    }
}
package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.springframework.jdbc.datasource.DelegatingDataSource;

/** The app's data source: the store itself, or for a request answered as of a date the sheet as it then stood. */
public class AsOfDataSource extends DelegatingDataSource {

    public AsOfDataSource(DataSource target) {
        super(target);
    }

    @Override
    public Connection getConnection() throws SQLException {
        DataSource store = AsOfContext.store();
        return store != null ? store.getConnection() : super.getConnection();
    }

    @Override
    public Connection getConnection(String username, String password) throws SQLException {
        DataSource store = AsOfContext.store();
        return store != null ? store.getConnection() : super.getConnection(username, password);
    }
}
package net.officefloor.hq.app.asof;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.settings.ViewerGuard;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * A screen showing a sheet as of a date sends that date with each request ({@link #HEADER}). Such a request is
 * answered from the sheet as it stood at the end of the date (see {@link AsOfService#storeAsOf}), and every request
 * that changes the sheet is refused before it reaches its handler, so it writes nothing. A handler marked
 * {@link AsOfReads} changes nothing and is answered as of the date.
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    /** The request header carrying the date the screen shows the sheet as of (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private final AsOfService asOf;

    public AsOfGuard(AsOfService asOf) {
        this.asOf = asOf;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String header = request.getHeader(HEADER);
        String sheetId = ViewerGuard.sheetId(request);
        if (header == null || header.isBlank() || !(handler instanceof HandlerMethod method) || sheetId == null) {
            return true;
        }
        LocalDate day;
        try {
            day = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
        }
        if (!HttpMethod.GET.matches(request.getMethod()) && !method.hasMethodAnnotation(AsOfReads.class)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of a date; nothing on it can change.");
        }
        AsOfContext.enter(asOf.storeAsOf(sheetId, day));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler,
            Exception ex) {
        AsOfContext.leave();
    }
}
package net.officefloor.hq.app.asof;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks a request that is not a GET yet changes nothing, so a screen showing the sheet as of a date may still make it
 * (and is answered as of that date): loading a sheet.
 */
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface AsOfReads {
}
